#!/usr/bin/env python3

# ----- AI USAGE DISCLOSURE ----
# This script was 100% generated by OpenAI's ChatGPT
# I (ms1d) do NOT take ownership of the code
# This is merely used to parse benchmark logs

import argparse
import json
import re
from pathlib import Path

CONFIG_RE = re.compile(
    r"NUM_THREADS:\s*(\d+)\s+NUM_TASKS:\s*(\d+)"
)


def parse_file(path):
    text = path.read_text(encoding="utf-8-sig")
    decoder = json.JSONDecoder()

    records = []
    config = None
    pos = 0

    while pos < len(text):
        line_end = text.find("\n", pos)
        if line_end < 0:
            line_end = len(text)

        line = text[pos:line_end].strip()
        match = CONFIG_RE.fullmatch(line)

        if match:
            config = {
                "num_threads": int(match[1]),
                "num_tasks": int(match[2]),
            }

        elif line.startswith("{"):
            start = pos + len(text[pos:line_end]) - len(
                text[pos:line_end].lstrip()
            )

            data, end = decoder.raw_decode(text, start)

            if config is None:
                raise ValueError(
                    f"Missing configuration before Hyperfine results in {path}"
                )

            if "schema_version" not in data or "results" not in data:
                raise ValueError(f"Invalid Hyperfine 2.0 JSON in {path}")

            for result in data["results"]:
                command = result["command"]

                records.append({
                    **config,
                    "benchmark": "ctor_dtor",
                    "command": command,
                    "executable": Path(command.split()[0]).name,
                    "hyperfine": result,
                })

            pos = end
            continue

        pos = line_end + 1

    return records


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=Path)
    parser.add_argument("-o", "--out-dir", type=Path)
    args = parser.parse_args()

    if args.input.is_file():
        files = [args.input]
    elif args.input.is_dir():
        files = sorted(args.input.glob("dump.*.*.txt"))
    else:
        parser.error(f"Input does not exist: {args.input}")

    if not files:
        parser.error("No input dump files found.")

    records = []
    for path in files:
        print(f"Parsing {path}")
        records.extend(parse_file(path))

    if not records:
        parser.error("No Hyperfine results found.")

    output_dir = args.out_dir or (
        args.input if args.input.is_dir() else args.input.parent
    )
    output_dir.mkdir(parents=True, exist_ok=True)

    output = output_dir / "benchmarks.json"
    output.write_text(
        json.dumps({"benchmarks": records}, indent=2) + "\n",
        encoding="utf-8",
    )

    print(f"Wrote {len(records)} results to {output}")


if __name__ == "__main__":
    main()
